import sys, subprocess, random

def find_reps(g, min_rep=1, min_len=1):
    n = len(g)
    occ = {}
    order = []
    for i in range(n):
        for j in range(1, n//2+1):
            if i + j <= n:
                key = tuple(g[i:i+j])
                if key not in occ:
                    occ[key] = []
                    order.append(key)
                occ[key].append(i)
    cands = []
    for key in order:
        idx = occ[key]
        if len(idx) < 2: continue
        L = len(key)
        ranges = []
        for s in idx:
            r = [s, s+L]
            if ranges and ranges[-1][1] == r[0]:
                ranges[-1][1] = r[1]
            else:
                ranges.append(r)
        for r in ranges:
            cnt = (r[1]-r[0])//L
            if cnt < 2: continue
            if cnt <= min_rep: continue
            if L < min_len: continue
            cands.append((r[0], r[1], key))
    cands.sort(key=lambda c: (-c[1], c[0]))
    sel = []
    for c in cands:
        if sel and c[1] > sel[-1][0]:
            continue
        sel.append(c)
    sel.reverse()
    return sel

def convert(g, min_rep, min_len):
    sel = find_reps(g, min_rep, min_len)
    out = []
    pos = 0
    for (s, e, key) in sel:
        out.extend(g[pos:s])
        unit = convert(list(key), min_rep, min_len)
        out.append(('rep', unit, (e-s)//len(key)))
        pos = e
    out.extend(g[pos:])
    return out

def render(seq):
    res = ''
    for x in seq:
        if isinstance(x, tuple):
            inner = render(x[1])
            single = len(x[1]) == 1 and not isinstance(x[1][0], tuple)
            if single: res += inner + '{%d}' % x[2]
            else: res += '(?:' + inner + '){%d}' % x[2]
        else:
            res += x
    return res

if __name__ == '__main__':
    random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
    bad = 0
    for t in range(300):
        n = random.randint(1, 14)
        alpha = random.choice(['ab', 'abc', 'aab'])
        s = ''.join(random.choice(alpha) for _ in range(n))
        mr = random.choice([1,1,1,2,3])
        ml = random.choice([1,1,1,2,3])
        exp = subprocess.run(['/workspace/executable', '-r', '--min-repetitions', str(mr), '--min-substring-length', str(ml), s], capture_output=True, text=True).stdout.strip()
        got = '^' + render(convert(list(s), mr, ml)) + '$'
        if exp != got:
            bad += 1
            if bad < 15: print(s, mr, ml, 'exp', exp, 'got', got)
    print('bad', bad)
