import json
data = json.load(open('/tmp/proto/repdata.json'))

def find_reps(g, min_rep, min_len, variant):
    n = len(g)
    occ = {}; order = []
    for i in range(n):
        for j in range(1, n//2+1):
            ok = (i + j <= n) if variant.get('occ','none')=='none' else (i + j < n) if variant['occ']=='strict' else (j <= (n-i)//2)
            if ok:
                key = tuple(g[i:i+j])
                if key not in occ: occ[key] = []; order.append(key)
                occ[key].append(i)
    cands = []
    for key in order:
        idx = occ[key]
        if len(idx) < 2: continue
        L = len(key)
        ranges = []
        for s in idx:
            r = [s, s+L]
            if ranges and ranges[-1][1] == r[0]: ranges[-1][1] = r[1]
            else: ranges.append(r)
        for r in ranges:
            cnt = (r[1]-r[0])//L
            if cnt < 2: continue
            if variant['filt'] == 'before':
                if cnt <= min_rep or L < min_len: continue
            cands.append((r[0], r[1], key))
    cands.sort(key=lambda c: (-c[1], c[0]))
    sel = []
