        if sel and c[1] > sel[-1][0]: continue
        sel.append(c)
    sel.reverse()
    if variant['filt'] == 'after':
        sel = [c for c in sel if (c[1]-c[0])//len(c[2]) > min_rep and len(c[2]) >= min_len]
    return sel

