    sel = find_reps(g, mr, ml, v)
    out = []; pos = 0
    for (s, e, key) in sel:
        out.extend(g[pos:s]); out.append(('rep', convert(list(key), mr, ml, v), (e-s)//len(key))); pos = e
    out.extend(g[pos:])
    return out

def render(seq):
    res = ''
    for x in seq:
        if isinstance(x, tuple):
            inner = render(x[1])
            single = len(x[1]) == 1 and not isinstance(x[1][0], tuple)
            res += (inner + '{%d}' % x[2]) if single else ('(?:' + inner + '){%d}' % x[2])
        else: res += x
    return res

for v in [dict(occ='none', filt='after'), dict(occ='strict', filt='after'), dict(occ='half', filt='after')]:
    bad = 0; ex = []
