//! Unicode character property lookups backed by regex-syntax tables.

use regex_syntax::hir::{Class, HirKind};
use std::sync::OnceLock;

pub struct CharSet {
    ranges: Vec<(char, char)>,
}

impl CharSet {
    fn from_pattern(pattern: &str) -> Self {
        let hir = regex_syntax::ParserBuilder::new()
            .unicode(true)
            .build()
            .parse(pattern)
            .expect("valid class pattern");
        let ranges = match hir.kind() {
            HirKind::Class(Class::Unicode(class)) => {
                class.ranges().iter().map(|r| (r.start(), r.end())).collect()
            }
            _ => panic!("pattern {} is not a unicode class", pattern),
        };
        CharSet { ranges }
    }

    pub fn contains(&self, c: char) -> bool {
        self.ranges
            .binary_search_by(|&(start, end)| {
                if c < start {
                    std::cmp::Ordering::Greater
                } else if c > end {
                    std::cmp::Ordering::Less
                } else {
                    std::cmp::Ordering::Equal
                }
            })
            .is_ok()
    }
}

macro_rules! charset {
    ($name:ident, $pattern:expr) => {
        pub fn $name(c: char) -> bool {
            static SET: OnceLock<CharSet> = OnceLock::new();
            SET.get_or_init(|| CharSet::from_pattern($pattern)).contains(c)
        }
    };
}

charset!(is_digit, r"\d");
charset!(is_space, r"\s");
charset!(is_word, r"\w");
