//! Output tokens used for rendering, colorizing and verbose formatting.

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Token {
    Text(String),
    ClassToken(String),
    Caret,
    Dollar,
    GroupOpen,
    GroupClose,
    Alternation,
    QuestionMark,
    Star,
    Repetition(String),
    ClassOpen,
    ClassClose,
    ClassHyphen,
    Flag(String),
}

impl Token {
    pub fn text(&self, capture_groups: bool) -> String {
        match self {
            Token::Text(s) | Token::ClassToken(s) | Token::Repetition(s) | Token::Flag(s) => s.clone(),
            Token::Caret => "^".to_string(),
            Token::Dollar => "$".to_string(),
            Token::GroupOpen => {
                if capture_groups {
                    "(".to_string()
                } else {
                    "(?:".to_string()
                }
            }
            Token::GroupClose => ")".to_string(),
            Token::Alternation => "|".to_string(),
            Token::QuestionMark => "?".to_string(),
            Token::Star => "*".to_string(),
            Token::ClassOpen => "[".to_string(),
            Token::ClassClose => "]".to_string(),
            Token::ClassHyphen => "-".to_string(),
        }
    }

    fn color(&self) -> Option<&'static str> {
        match self {
            Token::Text(_) => None,
            Token::ClassToken(_) => Some("103;30"),
            Token::Caret | Token::Dollar => Some("1;33"),
            Token::GroupOpen | Token::GroupClose => Some("1;32"),
            Token::Alternation => Some("1;31"),
            Token::QuestionMark | Token::Star => Some("1;35"),
            Token::Repetition(_) => Some("104;37"),
            Token::ClassOpen | Token::ClassClose | Token::ClassHyphen => Some("1;36"),
            Token::Flag(_) => Some("40;93"),
        }
    }

    pub fn render(&self, capture_groups: bool, colorize: bool) -> String {
        let text = self.text(capture_groups);
        match (colorize, self.color()) {
            (true, Some(code)) => format!("\x1b[{}m{}\x1b[0m", code, text),
            _ => text,
        }
    }
}
