//! Graphemes: the smallest units the regular expression is built from.

use crate::config::Config;
use crate::token::Token;
use crate::unicode;
use unicode_segmentation::UnicodeSegmentation;

/// A single component of a grapheme: either a raw character or a
/// shorthand character class that replaced a raw character.
#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Piece {
    Raw(char),
    Class(&'static str),
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Grapheme {
    /// Components of a simple grapheme (or of a repeated single grapheme).
    pub pieces: Vec<Piece>,
    /// Repeated unit consisting of several graphemes (empty otherwise).
    pub unit: Vec<Grapheme>,
    /// Value used for comparing graphemes regardless of their quantity.
    pub value: String,
    pub min: u32,
    pub max: u32,
}

const CLASS_TOKENS: [&str; 6] = ["\\d", "\\D", "\\s", "\\S", "\\w", "\\W"];

fn pieces_value(pieces: &[Piece]) -> String {
    let mut s = String::new();
    for p in pieces {
        match p {
            Piece::Raw(c) => s.push(*c),
            Piece::Class(t) => s.push_str(t),
        }
    }
    s
}

pub fn escape_unicode(c: char, surrogates: bool) -> String {
    let code = c as u32;
    if surrogates && (0x10000..0x10ffff).contains(&code) {
        let v = code - 0x10000;
        let high = 0xd800 + (v >> 10);
        let low = 0xdc00 + (v & 0x3ff);
        format!("\\u{{{:x}}}\\u{{{:x}}}", high, low)
    } else {
        format!("\\u{{{:x}}}", code)
    }
}

fn escape_raw_literal(c: char, cfg: &Config) -> String {
    match c {
        '\n' => "\\n".to_string(),
        '\r' => "\\r".to_string(),
        '\t' => "\\t".to_string(),
        '\u{0b}' => "\\v".to_string(),
        '\u{0c}' => "\\f".to_string(),
        '(' | ')' | '[' | ']' | '{' | '}' | '+' | '*' | '-' | '.' | '?' | '|' | '^' | '$' => {
            format!("\\{}", c)
        }
        _ if cfg.escape && !c.is_ascii() => escape_unicode(c, cfg.surrogates),
        _ => c.to_string(),
    }
}

pub fn escape_class_char(c: char, cfg: &Config) -> String {
    match c {
        '\n' => "\\n".to_string(),
        '\r' => "\\r".to_string(),
        '\t' => "\\t".to_string(),
        '\u{0b}' => "\\v".to_string(),
        '\u{0c}' => "\\f".to_string(),
        '[' | ']' | '\\' | '-' | '^' | '$' => format!("\\{}", c),
        _ if cfg.escape && !c.is_ascii() => escape_unicode(c, cfg.surrogates),
        _ => c.to_string(),
    }
}

impl Grapheme {
    pub fn simple(pieces: Vec<Piece>) -> Self {
        let value = pieces_value(&pieces);
        Grapheme {
            pieces,
            unit: vec![],
            value,
            min: 1,
            max: 1,
        }
    }

    pub fn is_simple(&self) -> bool {
        self.unit.is_empty() && self.min == 1 && self.max == 1
    }

    /// Number of characters, counting escaped non-ASCII characters by the
    /// length of their escape sequence.
    pub fn char_count(&self, cfg: &Config) -> usize {
        if !self.unit.is_empty() {
            return self.unit.iter().map(|g| g.char_count(cfg)).sum();
        }
        self.pieces
            .iter()
            .map(|p| match p {
                Piece::Raw(c) => {
                    if cfg.escape && !c.is_ascii() {
                        escape_unicode(*c, cfg.surrogates).chars().count()
                    } else {
                        1
                    }
                }
                Piece::Class(t) => t.len(),
            })
            .sum()
    }

    pub fn single_char(&self) -> Option<char> {
        if self.is_simple() && self.pieces.len() == 1 {
            if let Piece::Raw(c) = self.pieces[0] {
                return Some(c);
            }
        }
        None
    }

    fn escaped_pieces(&self, cfg: &Config) -> String {
        if self.pieces == [Piece::Raw('\\')] {
            return "\\\\".to_string();
        }
        let mut s = String::new();
        for p in &self.pieces {
            match p {
                Piece::Raw(c) => s.push_str(&escape_raw_literal(*c, cfg)),
                Piece::Class(t) => s.push_str(t),
            }
        }
        s
    }

    fn quantifier(&self) -> String {
        if self.min == self.max {
            format!("{{{}}}", self.min)
        } else {
            format!("{{{},{}}}", self.min, self.max)
        }
    }

    pub fn render(&self, cfg: &Config, out: &mut Vec<Token>) {
        if self.unit.is_empty() {
            let text = self.escaped_pieces(cfg);
            let is_single = text.chars().count() == 1 || text.matches('\\').count() == 1;
            let token = if cfg.colorize && CLASS_TOKENS.contains(&text.as_str()) {
                Token::ClassToken(text)
            } else {
                Token::Text(text)
            };
            if self.min == 1 && self.max == 1 {
                out.push(token);
            } else if is_single {
                out.push(token);
                out.push(Token::Repetition(self.quantifier()));
            } else {
                out.push(Token::GroupOpen);
                out.push(token);
                out.push(Token::GroupClose);
                out.push(Token::Repetition(self.quantifier()));
            }
        } else {
            out.push(Token::GroupOpen);
            for g in &self.unit {
                g.render(cfg, out);
            }
            out.push(Token::GroupClose);
            out.push(Token::Repetition(self.quantifier()));
        }
    }
}

/// Splits a test case into graphemes, applying all configured conversions.
pub fn graphemes_of(text: &str, cfg: &Config) -> Vec<Grapheme> {
    let mut result = vec![];
    for g in text.graphemes(true) {
        let chars: Vec<char> = g.chars().collect();
        let contains_backslash = chars.len() == 2 && chars.contains(&'\\');
        let contains_mark_or_other = chars.iter().any(|&c| unicode::is_mark_or_other(c));
        if contains_backslash || contains_mark_or_other {
            for c in chars {
                result.push(Grapheme::simple(vec![convert_char(c, cfg)]));
            }
        } else {
            result.push(Grapheme::simple(
                chars.into_iter().map(|c| convert_char(c, cfg)).collect(),
            ));
        }
    }
    if cfg.repetitions {
        result = convert_repetitions(&result, cfg);
    }
    result
}

fn convert_char(c: char, cfg: &Config) -> Piece {
    if !cfg.has_class_conversion() {
        return Piece::Raw(c);
    }
    let digit = unicode::is_digit(c);
    let space = unicode::is_space(c);
    let word = unicode::is_word(c);
    if cfg.digits && digit {
        Piece::Class("\\d")
    } else if cfg.spaces && space {
        Piece::Class("\\s")
    } else if cfg.words && word {
        Piece::Class("\\w")
    } else if cfg.non_digits && !digit {
        Piece::Class("\\D")
    } else if cfg.non_words && !word {
        Piece::Class("\\W")
    } else if cfg.non_spaces && !space {
        Piece::Class("\\S")
    } else {
        Piece::Raw(c)
    }
}

struct Candidate {
    start: usize,
    end: usize,
    len: usize,
}

fn convert_repetitions(graphemes: &[Grapheme], cfg: &Config) -> Vec<Grapheme> {
    let n = graphemes.len();
    let min_reps = cfg.min_repetitions as usize;
    let min_len = cfg.min_substring_length as usize;

    // Collect start indices of all substrings (by grapheme value).
    let mut occurrences: std::collections::HashMap<Vec<&str>, Vec<usize>> =
        std::collections::HashMap::new();
    let mut order: Vec<Vec<&str>> = vec![];
    for i in 0..n {
        for j in 1..=n / 2 {
            if i + j <= n {
                let key: Vec<&str> = graphemes[i..i + j].iter().map(|g| g.value.as_str()).collect();
                let entry = occurrences.entry(key.clone()).or_insert_with(|| {
                    order.push(key);
                    vec![]
                });
                entry.push(i);
            }
        }
    }

    let mut candidates = vec![];
    for key in &order {
        let indices = &occurrences[key];
        if indices.len() < 2 {
            continue;
        }
        let len = key.len();
        if indices.windows(2).any(|w| w[1] < w[0] + len) {
            continue;
        }
        let mut ranges: Vec<(usize, usize)> = vec![];
        for &s in indices {
            match ranges.last_mut() {
                Some(last) if last.1 == s => last.1 = s + len,
                _ => ranges.push((s, s + len)),
            }
        }
        for (start, end) in ranges {
            let count = (end - start) / len;
            if count < 2 || count <= min_reps {
                continue;
            }
            candidates.push(Candidate { start, end, len });
        }
    }

    candidates.sort_by(|a, b| b.end.cmp(&a.end).then(a.start.cmp(&b.start)).then(a.len.cmp(&b.len)));
    let mut selected: Vec<Candidate> = vec![];
    for c in candidates {
        if let Some(last) = selected.last() {
            if c.end > last.start {
                continue;
            }
        }
        selected.push(c);
    }
    selected.reverse();
    selected.retain(|c| c.len >= min_len);

    if selected.is_empty() {
        return graphemes.to_vec();
    }

    let mut result = vec![];
    let mut pos = 0;
    for c in selected {
        result.extend_from_slice(&graphemes[pos..c.start]);
        let unit_slice = &graphemes[c.start..c.start + c.len];
        let count = ((c.end - c.start) / c.len) as u32;
        let value: String = unit_slice.iter().map(|g| g.value.as_str()).collect();
        let grapheme = if c.len == 1 {
            Grapheme {
                pieces: unit_slice[0].pieces.clone(),
                unit: vec![],
                value,
                min: count,
                max: count,
            }
        } else {
            Grapheme {
                pieces: vec![],
                unit: convert_repetitions(unit_slice, cfg),
                value,
                min: count,
                max: count,
            }
        };
        result.push(grapheme);
        pos = c.end;
    }
    result.extend_from_slice(&graphemes[pos..]);
    result
}
EOF
echo ok

