        }
    }

    fn remove_suffix(&mut self, n: usize) {
        match self {
            Expr::Literal(g) => {
                let len = g.len();
                g.truncate(len - n);
            }
            Expr::Concatenation(_, b) => b.remove_suffix(n),
            _ => {}
        }
    }

    // ---------------------------------------------------------------- rendering

    pub fn render(&self, cfg: &Config, out: &mut Vec<Token>) {
        match self {
            Expr::Alternation(options) => {
                for (i, option) in options.iter().enumerate() {
                    if i > 0 {
                        out.push(Token::Alternation);
                    }
                    self.render_child(option, cfg, out);
                }
            }
            Expr::CharClass(set) => render_char_class(set, cfg, out),
            Expr::Concatenation(a, b) => {
                self.render_child(a, cfg, out);
                self.render_child(b, cfg, out);
            }
            Expr::Literal(graphemes) => {
                for g in graphemes {
                    g.render(cfg, out);
                }
            }
            Expr::Repetition(e, q) => {
                self.render_child(e, cfg, out);
                out.push(match q {
                    Quantifier::QuestionMark => Token::QuestionMark,
                    Quantifier::KleeneStar => Token::Star,
                });
            }
        }
    }

    fn render_child(&self, child: &Expr, cfg: &Config, out: &mut Vec<Token>) {
        if child.precedence() < self.precedence() && !child.is_single_codepoint(cfg) {
            out.push(Token::GroupOpen);
            child.render(cfg, out);
            out.push(Token::GroupClose);
        } else {
            child.render(cfg, out);
        }
    }
}

fn render_char_class(set: &BTreeSet<char>, cfg: &Config, out: &mut Vec<Token>) {
    out.push(Token::ClassOpen);
    let chars: Vec<char> = set.iter().copied().collect();
    let mut i = 0;
    while i < chars.len() {
        let mut j = i;
        while j + 1 < chars.len() && (chars[j + 1] as u32) == (chars[j] as u32) + 1 {
            j += 1;
        }
        let run = j - i + 1;
        if run >= 3 {
            out.push(Token::Text(escape_class_char(chars[i], cfg)));
            out.push(Token::ClassHyphen);
            out.push(Token::Text(escape_class_char(chars[j], cfg)));
        } else {
            for &c in &chars[i..=j] {
                out.push(Token::Text(escape_class_char(c, cfg)));
            }
        }
        i = j + 1;
    }
    out.push(Token::ClassClose);
}

fn common_prefix_len(a: &[Grapheme], b: &[Grapheme]) -> usize {
    a.iter().zip(b.iter()).take_while(|(x, y)| x == y).count()
}

fn common_suffix_len(a: &[Grapheme], b: &[Grapheme]) -> usize {
    a.iter().rev().zip(b.iter().rev()).take_while(|(x, y)| x == y).count()
}

fn remove_common_prefix(a: &mut Expr, b: &mut Expr) -> Option<Vec<Grapheme>> {
    let (pa, pb) = (a.literal_prefix()?, b.literal_prefix()?);
    let n = common_prefix_len(pa, pb);
    if n == 0 {
        return None;
    }
    let prefix = pa[..n].to_vec();
    a.remove_prefix(n);
    b.remove_prefix(n);
    Some(prefix)
}

fn remove_common_suffix(a: &mut Expr, b: &mut Expr) -> Option<Vec<Grapheme>> {
    let (sa, sb) = (a.literal_suffix()?, b.literal_suffix()?);
    let n = common_suffix_len(sa, sb);
    if n == 0 {
        return None;
    }
    let suffix = sa[sa.len() - n..].to_vec();
    a.remove_suffix(n);
    b.remove_suffix(n);
    Some(suffix)
}

pub fn union(a: Option<Expr>, b: Option<Expr>, cfg: &Config) -> Option<Expr> {
    match (a, b) {
        (Some(a), Some(b)) => {
            if a == b {
                return Some(a);
            }
            let (mut a, mut b) = (a, b);
            let prefix = remove_common_prefix(&mut a, &mut b);
            let suffix = remove_common_suffix(&mut a, &mut b);

            let mut result = if a.is_empty() {
                Expr::Repetition(Box::new(b), Quantifier::QuestionMark)
            } else if b.is_empty() {
                Expr::Repetition(Box::new(a), Quantifier::QuestionMark)
            } else if let Expr::Repetition(inner, Quantifier::QuestionMark) = &a {
                let u = union(Some((**inner).clone()), Some(b), cfg).unwrap();
                Expr::Repetition(Box::new(u), Quantifier::QuestionMark)
            } else if let Expr::Repetition(inner, Quantifier::QuestionMark) = &b {
                let u = union(Some(a), Some((**inner).clone()), cfg).unwrap();
                Expr::Repetition(Box::new(u), Quantifier::QuestionMark)
            } else if a.is_single_codepoint(cfg) && b.is_single_codepoint(cfg) {
                let mut set = a.char_set();
                set.extend(b.char_set());
                Expr::CharClass(set)
            } else {
                Expr::new_alternation(a, b)
            };

            if let Some(prefix) = prefix {
                result = Expr::Concatenation(Box::new(Expr::Literal(prefix)), Box::new(result));
            }
            if let Some(suffix) = suffix {
                result = Expr::Concatenation(Box::new(result), Box::new(Expr::Literal(suffix)));
            }
            Some(result)
        }
        (Some(a), None) => Some(a),
        (None, b) => b,
    }
}

pub fn concatenate(a: Option<Expr>, b: Option<Expr>) -> Option<Expr> {
    let (a, b) = match (a, b) {
        (Some(a), Some(b)) => (a, b),
        _ => return None,
    };
    if a.is_empty() {
        return Some(b);
    }
    if b.is_empty() {
        return Some(a);
    }
    match (a, b) {
        (Expr::Literal(mut x), Expr::Literal(y)) => {
            x.extend(y);
            Some(Expr::Literal(x))
        }
        (Expr::Literal(mut x), Expr::Concatenation(first, second)) if matches!(*first, Expr::Literal(_)) => {
            if let Expr::Literal(y) = *first {
                x.extend(y);
            }
            Some(Expr::Concatenation(Box::new(Expr::Literal(x)), second))
        }
        (Expr::Concatenation(first, second), Expr::Literal(y)) if matches!(*second, Expr::Literal(_)) => {
            let mut x = match *second {
                Expr::Literal(x) => x,
                _ => unreachable!(),
            };
            x.extend(y);
            Some(Expr::Concatenation(first, Box::new(Expr::Literal(x))))
        }
        (a, b) => Some(Expr::Concatenation(Box::new(a), Box::new(b))),
    }
}

pub fn star(e: Option<Expr>) -> Option<Expr> {
    e.map(|e| Expr::Repetition(Box::new(e), Quantifier::KleeneStar))
}
