        for seq in sequences {
            dfa.insert(seq);
        }
        dfa.minimize();
        dfa
    }

    fn insert(&mut self, seq: &[Grapheme]) {
        let mut state = self.initial;
        for g in seq {
            state = match self.find_next_state(state, g) {
                Some(next) => next,
                None => {
                    let next = self.edges.len();
                    self.edges.push(vec![]);
                    self.edges[state].push(Edge {
                        target: next,
                        label: g.clone(),
                    });
                    next
                }
            };
        }
        self.finals.insert(state);
    }

    fn find_next_state(&mut self, state: usize, g: &Grapheme) -> Option<usize> {
        for edge in self.edges[state].iter_mut().rev() {
            let label = &mut edge.label;
            if label.value != g.value || label.unit != g.unit || label.pieces != g.pieces {
                continue;
            }
            if label.max + 1 == g.min {
                label.max = g.max;
                return Some(edge.target);
            } else if label.max == g.min {
                return Some(edge.target);
            }
        }
        None
    }

    fn minimize(&mut self) {
        let n = self.edges.len();
        // Moore-style partition refinement.
        let mut class: Vec<usize> = (0..n)
            .map(|s| if self.finals.contains(&s) { 0 } else { 1 })
            .collect();
        let mut count = class.iter().collect::<HashSet<_>>().len();
        loop {
            let mut ids: HashMap<(usize, Vec<(Grapheme, usize)>), usize> = HashMap::new();
            let mut next = vec![0; n];
            for s in 0..n {
                let mut sig: Vec<(Grapheme, usize)> = self.edges[s]
                    .iter()
                    .map(|e| (e.label.clone(), class[e.target]))
                    .collect();
                sig.sort();
                let key = (class[s], sig);
                let len = ids.len();
                next[s] = *ids.entry(key).or_insert(len);
            }
            let new_count = ids.len();
            class = next;
            if new_count == count {
                break;
            }
            count = new_count;
        }

        // Recreate the graph with one state per equivalence class.
        let mut mapping: BTreeMap<usize, usize> = BTreeMap::new();
        for s in 0..n {
            let len = mapping.len();
            mapping.entry(class[s]).or_insert(len);
        }
        let new_n = mapping.len();
        let new_state = |s: usize| mapping[&class[s]];
        let mut edges: Vec<Vec<Edge>> = (0..new_n).map(|_| vec![]).collect();
        let mut finals = HashSet::new();
        for src in 0..n {
            for edge in self.edges[src].iter().rev() {
                let ns = new_state(src);
                let nt = new_state(edge.target);
                let exists = edges[ns]
                    .iter()
                    .any(|e| e.target == nt && e.label == edge.label);
                if !exists {
                    edges[ns].push(Edge {
                        target: nt,
                        label: edge.label.clone(),
                    });
                }
                if self.finals.contains(&edge.target) {
                    finals.insert(nt);
                }
            }
        }
        self.initial = new_state(self.initial);
        self.edges = edges;
        self.finals = finals;
    }

    fn states_in_depth_first_order(&self) -> Vec<usize> {
        let mut stack = vec![self.initial];
        let mut discovered = vec![false; self.edges.len()];
        let mut order = vec![];
        while let Some(node) = stack.pop() {
            if discovered[node] {
                continue;
            }
            discovered[node] = true;
            for edge in self.edges[node].iter().rev() {
                if !discovered[edge.target] {
                    stack.push(edge.target);
                }
            }
            order.push(node);
        }
        order
    }

    pub fn to_expression(&self, cfg: &Config) -> Expr {
        let states = self.states_in_depth_first_order();
        let n = states.len();
        let mut index = vec![usize::MAX; self.edges.len()];
        for (i, &s) in states.iter().enumerate() {
            index[s] = i;
        }
        let mut a: Vec<Vec<Option<Expr>>> = vec![vec![None; n]; n];
        let mut b: Vec<Option<Expr>> = vec![None; n];
        for (i, &s) in states.iter().enumerate() {
            if self.finals.contains(&s) {
                b[i] = Some(Expr::empty());
            }
            for edge in self.edges[s].iter().rev() {
                let j = index[edge.target];
                let literal = Expr::Literal(vec![edge.label.clone()]);
                a[i][j] = match a[i][j].take() {
                    Some(existing) => union(Some(existing), Some(literal), cfg),
                    None => Some(literal),
                };
            }
        }

        for k in (0..n).rev() {
            if a[k][k].is_some() {
                let loop_expr = star(a[k][k].clone());
                b[k] = concatenate(loop_expr.clone(), b[k].take());
                for j in 0..k {
                    a[k][j] = concatenate(loop_expr.clone(), a[k][j].take());
                }
            }
            for i in 0..k {
                if a[i][k].is_some() {
                    let aik = a[i][k].clone();
                    b[i] = union(b[i].take(), concatenate(aik.clone(), b[k].clone()), cfg);
                    for j in 0..k {
                        a[i][j] = union(a[i][j].take(), concatenate(aik.clone(), a[k][j].clone()), cfg);
                    }
                }
            }
        }
        b[0].take().unwrap_or_else(Expr::empty)
    }
}
