//! Assembly of the final regular expression string.

use crate::config::Config;
use crate::dfa::Dfa;
use crate::expression::Expr;
use crate::grapheme::graphemes_of;
use crate::token::Token;

fn lowercase(test_case: &str) -> String {
    let lower = test_case.to_lowercase();
    if lower.chars().count() == test_case.chars().count() {
        lower
    } else {
        test_case.to_string()
    }
}

pub fn generate(test_cases: &[String], cfg: &Config) -> String {
    let mut cases: Vec<String> = if cfg.ignore_case {
        test_cases.iter().map(|t| lowercase(t)).collect()
    } else {
        test_cases.to_vec()
    };
    cases.sort();
    cases.dedup();
    cases.sort_by_key(|t| t.len());

    let sequences: Vec<_> = cases.iter().map(|t| graphemes_of(t, cfg)).collect();
    let dfa = Dfa::from(&sequences);
    let expr = dfa.to_expression(cfg);
    render(&expr, cfg)
}

fn render(expr: &Expr, cfg: &Config) -> String {
    let mut body = vec![];
    if let Expr::Alternation(_) = expr {
        body.push(Token::GroupOpen);
        expr.render(cfg, &mut body);
        body.push(Token::GroupClose);
    } else {
        expr.render(cfg, &mut body);
    }

    let flag = match (cfg.ignore_case, cfg.verbose) {
        (true, true) => Some("(?ix)"),
        (true, false) => Some("(?i)"),
        (false, true) => Some("(?x)"),
        (false, false) => None,
    };

    if cfg.verbose {
        render_verbose(body, flag, cfg)
    } else {
        let mut tokens = vec![];
        if let Some(f) = flag {
            tokens.push(Token::Flag(f.to_string()));
        }
        if !cfg.no_start_anchor {
            tokens.push(Token::Caret);
        }
        tokens.extend(body);
        if !cfg.no_end_anchor {
            tokens.push(Token::Dollar);
        }
        tokens
            .iter()
            .map(|t| t.render(cfg.capture_groups, cfg.colorize))
            .collect()
    }
}

fn escape_for_verbose(text: &str) -> String {
    let mut s = String::new();
    for c in text.chars() {
        match c {
            ' ' => s.push_str("\\ "),
            '#' => s.push_str("\\#"),
            c if c.is_whitespace() => s.push_str("\\s"),
            c => s.push(c),
        }
    }
    s
}

fn render_verbose(body: Vec<Token>, flag: Option<&str>, cfg: &Config) -> String {
    let body: Vec<Token> = body
        .into_iter()
        .map(|t| match t {
            Token::Text(s) => Token::Text(escape_for_verbose(&s)),
            other => other,
        })
        .collect();

    let mut lines: Vec<(usize, Vec<Token>)> = vec![];
    let mut level = 1usize;
    let mut current: Vec<Token> = vec![];
    let mut i = 0;
    while i < body.len() {
        let token = body[i].clone();
        match token {
            Token::GroupOpen => {
                if !current.is_empty() {
                    lines.push((level, std::mem::take(&mut current)));
                }
                lines.push((level, vec![token]));
                level += 1;
            }
            Token::GroupClose => {
                if !current.is_empty() {
                    lines.push((level, std::mem::take(&mut current)));
                }
                level = level.saturating_sub(1);
                let mut line = vec![token];
                while i + 1 < body.len() {
                    match &body[i + 1] {
                        Token::QuestionMark | Token::Star | Token::Repetition(_) => {
                            line.push(body[i + 1].clone());
                            i += 1;
                        }
                        _ => break,
                    }
                }
                lines.push((level, line));
            }
            Token::Alternation => {
                if !current.is_empty() {
                    lines.push((level, std::mem::take(&mut current)));
                }
                lines.push((level, vec![token]));
            }
            Token::QuestionMark | Token::Star => {
                current.push(token);
                lines.push((level, std::mem::take(&mut current)));
            }
            other => current.push(other),
        }
        i += 1;
    }
    if !current.is_empty() {
        lines.push((level, current));
    }

    let render_tokens = |tokens: &[Token]| -> String {
        tokens
            .iter()
            .map(|t| t.render(cfg.capture_groups, cfg.colorize))
            .collect()
    };

    let mut out: Vec<String> = vec![];
    if let Some(f) = flag {
        out.push(Token::Flag(f.to_string()).render(cfg.capture_groups, cfg.colorize));
    }
    if !cfg.no_start_anchor {
        out.push(Token::Caret.render(cfg.capture_groups, cfg.colorize));
    }
    for (level, tokens) in &lines {
        out.push(format!("{}{}", "  ".repeat(*level), render_tokens(tokens)));
    }
    if !cfg.no_end_anchor {
        out.push(Token::Dollar.render(cfg.capture_groups, cfg.colorize));
    }
    out.join("\n")
}
