fn flat_alternation(sequences: &[Vec<crate::grapheme::Grapheme>]) -> Expr {
    let mut options: Vec<Expr> = sequences.iter().map(|s| Expr::Literal(s.clone())).collect();
    options.sort_by(|a, b| b.len().cmp(&a.len()));
    if options.len() == 1 {
