    } else {
        Expr::Alternation(options)
    }
}

/// Renders the expression the way it is compiled for validating the result.
fn pattern_string(expr: &Expr, cfg: &Config, verbose: bool) -> String {
    let plain_cfg = Config {
        colorize: false,
        ..cfg.clone()
    };
    let mut tokens = vec![];
    expr.render(&plain_cfg, &mut tokens);
    let mut s = String::new();
    for t in &tokens {
        let text = t.text(cfg.capture_groups);
        if verbose {
            match t {
                Token::GroupOpen => s.push_str(&format!("\\n{}\\n", text)),
                Token::GroupClose => s.push_str(&format!("\\n{}", text)),
                Token::Alternation => s.push_str("\\n|\\n"),
                Token::QuestionMark | Token::Star => s.push_str(&format!("{}\\n", text)),
                _ => s.push_str(&text),
            }
        } else {
            s.push_str(&text);
        }
    }
    s
}

