//! Minimal terminal size detection (stdout, then stderr, then stdin).

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

#[cfg(unix)]
mod sys {
    use std::os::raw::{c_int, c_ulong};

    #[repr(C)]
    #[derive(Default)]
    pub struct WinSize {
        pub ws_row: u16,
        pub ws_col: u16,
        pub ws_xpixel: u16,
        pub ws_ypixel: u16,
    }

    #[cfg(any(target_os = "linux", target_os = "android"))]
    pub const TIOCGWINSZ: c_ulong = 0x5413;
    #[cfg(not(any(target_os = "linux", target_os = "android")))]
    pub const TIOCGWINSZ: c_ulong = 0x40087468;

    extern "C" {
        pub fn isatty(fd: c_int) -> c_int;
        pub fn ioctl(fd: c_int, request: c_ulong, ...) -> c_int;
    }

    pub fn size_of_fd(fd: c_int) -> Option<(u16, u16)> {
        unsafe {
            if isatty(fd) != 1 {
                return None;
            }
            let mut ws = WinSize::default();
            if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) == -1 {
                return None;
            }
            if ws.ws_row > 0 && ws.ws_col > 0 {
                Some((ws.ws_col, ws.ws_row))
            } else {
                None
            }
        }
    }
}

/// Returns the size of the terminal attached to stdout, stderr or stdin (in this order).
#[cfg(unix)]
pub fn terminal_size() -> Option<(Width, Height)> {
    [1, 2, 0]
        .iter()
        .find_map(|&fd| sys::size_of_fd(fd))
        .map(|(w, h)| (Width(w), Height(h)))
}

#[cfg(not(unix))]
pub fn terminal_size() -> Option<(Width, Height)> {
    None
}
